#!/usr/bin/env bash
# File: clients/revpi-led/install.sh
# Purpose: Optionally install or update the standalone RevPi LED client.
# Generated by: aiAgentTseiman (Hermes Agent)
# Generated on: 2026-10-13

set -euo pipefail

readonly SERVICE_NAME="automation-gateway-led"
readonly SERVICE_USER="automation-gateway-led"
readonly SERVICE_GROUP="automation-gateway-led"
readonly PICONTROL_GROUP="picontrol"
readonly BINARY_TARGET="/usr/local/sbin/automation-gateway-led"
readonly CONFIG_DIR="/etc/automation-gateway-led"
readonly CONFIG_TARGET="$CONFIG_DIR/config.yaml"
readonly UNIT_TARGET="/etc/systemd/system/automation-gateway-led.service"

SCRIPT_PATH="$(readlink -f -- "${BASH_SOURCE[0]}")"
COMPONENT_DIR="$(CDPATH= cd -- "$(dirname -- "$SCRIPT_PATH")" && pwd -P)"
PROJECT_ROOT="$(CDPATH= cd -- "$COMPONENT_DIR/../.." && pwd -P)"
SOURCE_BINARY=""
BUILD_TEMP=""
START=false

usage() {
    cat <<'USAGE'
Usage: ./clients/revpi-led/install.sh [--binary=PATH] [--start]

Without --binary, build the LED client from the current repository checkout.
The installer is optional and never runs from the gateway installer.

Options:
  --binary=PATH  Install an already cross-compiled automation-gateway-led binary.
  --start        Validate configuration/device access and enable/start the service.
  --help, -h     Show this help.
USAGE
}

log() { printf '[led-install] %s\n' "$*"; }
die() { printf '[led-install] ERROR: %s\n' "$*" >&2; exit 1; }
cleanup() { [[ -z "$BUILD_TEMP" ]] || rm -f -- "$BUILD_TEMP"; }
trap cleanup EXIT

require_command() { command -v -- "$1" >/dev/null 2>&1 || die "required command not found: $1"; }
reject_symlink() { [[ ! -L "$1" ]] || die "refusing symlink target: $1"; }
require_regular() { [[ -f "$1" && ! -L "$1" ]] || die "required regular non-symlink file: $1"; }

install_atomic() {
    local source="$1" target="$2" mode="$3" temporary
    reject_symlink "$target"
    temporary="$(mktemp -- "${target}.candidate.XXXXXX")"
    if ! install -o root -g root -m "$mode" -- "$source" "$temporary" || ! mv -fT -- "$temporary" "$target"; then
        rm -f -- "$temporary"
        return 1
    fi
}

ensure_identity() {
    getent group "$PICONTROL_GROUP" >/dev/null || die "group '$PICONTROL_GROUP' is missing; install/enable the RevPi piControl packages first"
    if ! getent group "$SERVICE_GROUP" >/dev/null; then
        addgroup --system "$SERVICE_GROUP"
    fi
    if ! getent passwd "$SERVICE_USER" >/dev/null; then
        adduser --system --ingroup "$SERVICE_GROUP" --no-create-home --home /nonexistent --shell /usr/sbin/nologin "$SERVICE_USER"
    fi
    usermod -a -G "$PICONTROL_GROUP" "$SERVICE_USER"
}

build_binary() {
    require_command go
    require_command git
    [[ -f "$PROJECT_ROOT/go.mod" ]] || die "go.mod not found; packaged installs must pass --binary"
    local build_version build_commit build_time ldflags
    build_version="$(git -C "$PROJECT_ROOT" describe --tags --always --dirty)"
    build_commit="$(git -C "$PROJECT_ROOT" rev-parse HEAD)"
    build_time="$(git -C "$PROJECT_ROOT" show -s --format=%cI HEAD)"
    [[ "$build_version" =~ ^[0-9A-Za-z._+-]+$ ]] || die "unsafe version string"
    [[ "$build_commit" =~ ^[0-9a-f]{40}$ ]] || die "invalid Git commit"
    [[ "$build_time" =~ ^[0-9T:+-]+$ ]] || die "invalid Git timestamp"
    BUILD_TEMP="$(mktemp -- "${TMPDIR:-/tmp}/automation-gateway-led.build.XXXXXX")"
    ldflags="-s -w -X main.version=$build_version -X main.commit=$build_commit -X main.buildTime=$build_time"
    (cd "$PROJECT_ROOT" && CGO_ENABLED=0 GOTOOLCHAIN=local go build -trimpath -ldflags "$ldflags" -o "$BUILD_TEMP" ./clients/revpi-led)
    chmod 0755 -- "$BUILD_TEMP"
    SOURCE_BINARY="$BUILD_TEMP"
}

while [[ $# -gt 0 ]]; do
    case "$1" in
        --binary)
            [[ $# -ge 2 ]] || die "--binary requires a path"
            SOURCE_BINARY="$(readlink -f -- "$2")"
            shift 2
            ;;
        --binary=*)
            [[ -n "${1#*=}" ]] || die "--binary requires a path"
            SOURCE_BINARY="$(readlink -f -- "${1#*=}")"
            shift
            ;;
        --start)
            START=true
            shift
            ;;
        --help|-h)
            usage
            exit 0
            ;;
        *) die "unknown argument: $1" ;;
    esac
done

if [[ -z "$SOURCE_BINARY" ]]; then
    build_binary
fi
require_regular "$SOURCE_BINARY"
require_regular "$COMPONENT_DIR/config.example.yaml"
require_regular "$COMPONENT_DIR/systemd/automation-gateway-led.service"

if [[ "$(id -u)" != "0" ]]; then
    require_command sudo
    arguments=(--binary "$SOURCE_BINARY")
    [[ "$START" == "true" ]] && arguments+=(--start)
    exec sudo -- "$SCRIPT_PATH" "${arguments[@]}"
fi

for command in addgroup adduser getent install mktemp mv runuser systemctl systemd-analyze usermod; do
    require_command "$command"
done
ensure_identity

reject_symlink "$CONFIG_DIR"
if [[ -e "$CONFIG_DIR" && ! -d "$CONFIG_DIR" ]]; then
    die "expected directory: $CONFIG_DIR"
fi
install -d -o root -g "$SERVICE_GROUP" -m 0750 -- "$CONFIG_DIR"
reject_symlink "$CONFIG_TARGET"
if [[ ! -e "$CONFIG_TARGET" ]]; then
    install -o root -g "$SERVICE_GROUP" -m 0640 -- "$COMPONENT_DIR/config.example.yaml" "$CONFIG_TARGET"
    log "installed initial configuration $CONFIG_TARGET"
else
    [[ -f "$CONFIG_TARGET" ]] || die "expected regular configuration: $CONFIG_TARGET"
    log "preserved existing configuration $CONFIG_TARGET"
fi

install_atomic "$SOURCE_BINARY" "$BINARY_TARGET" 0755 || die "failed to install binary"
install_atomic "$COMPONENT_DIR/systemd/automation-gateway-led.service" "$UNIT_TARGET" 0644 || die "failed to install systemd unit"
systemd-analyze verify "$UNIT_TARGET"
systemctl daemon-reload
log "installed optional LED client"

if [[ "$START" == "true" ]]; then
    [[ -c /dev/piControl0 ]] || die "/dev/piControl0 is not available"
    runuser -u "$SERVICE_USER" -- "$BINARY_TARGET" --config "$CONFIG_TARGET" --check
    runuser -u "$SERVICE_USER" -- test -r /dev/piControl0 || die "$SERVICE_USER cannot read /dev/piControl0"
    runuser -u "$SERVICE_USER" -- test -w /dev/piControl0 || die "$SERVICE_USER cannot write /dev/piControl0"
    systemctl enable --now "$SERVICE_NAME"
    log "enabled and started $SERVICE_NAME"
elif systemctl is-active --quiet "$SERVICE_NAME"; then
    runuser -u "$SERVICE_USER" -- "$BINARY_TARGET" --config "$CONFIG_TARGET" --check
    systemctl restart "$SERVICE_NAME"
    log "restarted active $SERVICE_NAME"
else
    log "service remains disabled/inactive; provision token and URL, then rerun with --start"
fi
